			fmt.Fprintf(os.Stderr, "moe gemv %s %s: block=%d does not admit %d weights per load at K=%d, skipping\n",
				s.layer, v.name, v.block, v.weightsPerLoad, s.K)
			continue
		}
		usable = append(usable, v)
		if ldw > maxLdw {
			maxLdw = ldw
		}
		if v.block < minBlock {
			minBlock = v.block
		}
	}
	if len(usable) == 0 {
		return nil, nil
	}
	for _, t := range tokens {
